-- End-to-end comment regression, including real authenticated RLS contexts.
begin;
-- Isolated fixture only. Application defaults remain manual after ROLLBACK.
update teplo_private.demo_venue_acceptance set auto_confirm_enabled=true;
do $$
declare buyer uuid; rider uuid; staff_id uuid; shop uuid; oid uuid; blank_oid uuid; jid uuid; items jsonb; req uuid:=gen_random_uuid();
 note text:=E'Без лука.\nПодъезд 2, домофон не работает. <b>Позвоните</b>'; due timestamptz; before_comments jsonb;
begin
 select coalesce(jsonb_object_agg(id::text,customer_comment),'{}'::jsonb) into before_comments from public.orders;
 select p.id into buyer from public.profiles p join auth.users u on u.id=p.id where p.role='courier' and u.email_confirmed_at is not null and not exists(select 1 from public.shop_members m where m.user_id=p.id) limit 1;
 select p.id into rider from public.profiles p join auth.users u on u.id=p.id where p.role='courier' and p.id<>buyer and u.email_confirmed_at is not null and exists(select 1 from public.courier_shifts s where s.courier_id=p.id and s.ended_at is null) and (select count(*) from public.teplo_pilot_jobs j where j.courier_id=p.id and j.status in ('assigned','accepted','picked_up'))<2 limit 1;
 select p.id into staff_id from public.profiles p join auth.users u on u.id=p.id where p.role='admin' and u.email_confirmed_at is not null limit 1;
 if buyer is null or rider is null or staff_id is null then raise exception 'Requires two verified couriers and an administrator';end if;
 select jsonb_agg(jsonb_build_object('product_id',id,'quantity',1)) into items from(select distinct on(p.shop_id) p.id from public.products p join teplo_private.demo_venue_acceptance d on d.shop_id=p.shop_id where p.is_available order by p.shop_id,p.id) products;
 if jsonb_array_length(items)<>2 then raise exception 'Requires two demo venues';end if;
 select p.shop_id into shop from public.products p where p.id=(items->0->>'product_id')::uuid;
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 set local role authenticated;
 oid:=public.place_teplo_demo_commented_cart(items,'Тест комментария','0000000000','Тестовая улица','1','','cash_on_delivery',req,'teplodar',note);
 set constraints all immediate;
 if (select customer_comment from public.orders where id=oid) is distinct from note then raise exception 'Buyer comment not saved';end if;
 if public.place_teplo_demo_commented_cart(items,'Тест комментария','0000000000','Тестовая улица','1','','cash_on_delivery',req,'teplodar','Другая запись после повтора')<>oid then raise exception 'Commented retry duplicated checkout';end if;
 if (select customer_comment from public.orders where id=oid) is distinct from note then raise exception 'Retry overwrote submitted comment';end if;
 begin perform public.place_teplo_demo_commented_cart(items,'Тест комментария','0000000000','Тестовая улица','1','','cash_on_delivery',gen_random_uuid(),'teplodar',repeat('я',501));raise exception 'ASSERT: oversized comment accepted';exception when others then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 begin perform public.place_teplo_demo_commented_cart(items,'Тест комментария','0000000000','Тестовая улица','1','','cash_on_delivery',gen_random_uuid(),'teplodar','text'||chr(1));raise exception 'ASSERT: control character accepted';exception when others then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 blank_oid:=public.place_teplo_demo_commented_cart(items,'Тест пустого комментария','0000000000','Тестовая улица','2','','cash_on_delivery',gen_random_uuid(),'teplodar',null);
 if (select customer_comment from public.orders where id=blank_oid)<>'' then raise exception 'Optional comment is not empty';end if;
 reset role;
 select id into jid from public.teplo_pilot_jobs where source_order_id=oid;
 if jid is null then raise exception 'Commented checkout did not reach courier queue';end if;
 set local role authenticated;
 if not exists(select 1 from jsonb_array_elements(public.teplo_job_customer_comments(array[jid])) x where x->>'customer_comment'=note) then raise exception 'Buyer cannot read own delivery comment';end if;
 perform set_config('request.jwt.claim.sub',rider::text,true);
 if jsonb_array_length(public.teplo_job_customer_comments(array[jid]))<>0 then raise exception 'Comment leaked to unassigned courier';end if;
 perform set_config('request.jwt.claim.sub',staff_id::text,true);
 if not exists(select 1 from jsonb_array_elements(public.teplo_job_customer_comments(array[jid])) x where x->>'customer_comment'=note) then raise exception 'Dispatcher comment missing';end if;
 if (select count(*) from jsonb_array_elements(public.teplo_venue_order_board()) x where x->>'order_id'=oid::text and x->>'customer_comment'=note)<>2 then raise exception 'Comment not sent to both venues';end if;
 reset role;
 update public.profiles set role='venue' where id=buyer;
 insert into public.shop_members(shop_id,user_id) values(shop,buyer);
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 set local role authenticated;
 if (select count(*) from jsonb_array_elements(public.teplo_venue_order_board()) x where x->>'order_id'=oid::text and x->>'customer_comment'=note and x->>'shop_id'=shop::text)<>1 then raise exception 'Scoped venue cannot read buyer comment';end if;
 if exists(select 1 from jsonb_array_elements(public.teplo_venue_order_board()) x where x->>'order_id'=oid::text and x->>'shop_id'<>shop::text) then raise exception 'Venue can see another venue task';end if;
 reset role;
 update public.profiles set role='courier' where id=buyer;
 perform set_config('request.jwt.claim.sub',rider::text,true);
 set local role authenticated;
 perform public.teplo_pilot_claim_job(jid);
 if not exists(select 1 from jsonb_array_elements(public.teplo_job_customer_comments(array[jid])) x where x->>'customer_comment'=note) then raise exception 'Assigned courier comment missing';end if;
 perform public.teplo_pilot_courier_step(jid,'picked_up');
 reset role;
 select delivery_due_at into due from public.teplo_pilot_jobs where id=jid;
 set local role authenticated;
 perform public.teplo_job_customer_comments(array[jid]);
 perform public.teplo_pilot_courier_step(jid,'delivered');
 if (select count(*) from public.teplo_pilot_earnings where job_id=jid)<>1 then raise exception 'Commented checkout earnings incorrect';end if;
 if not exists(select 1 from jsonb_array_elements(public.teplo_job_customer_comments(array[jid])) x where x->>'customer_comment'=note) then raise exception 'History comment disappeared';end if;
 perform set_config('request.jwt.claim.sub',buyer::text,true);
 if (select customer_comment from public.orders where id=oid) is distinct from note then raise exception 'Buyer comment disappeared after completion';end if;
 reset role;
 if (select delivery_due_at from public.teplo_pilot_jobs where id=jid) is distinct from due then raise exception 'Reading comment changed delivery deadline';end if;
 if exists(select 1 from public.orders o where before_comments ? o.id::text and o.customer_comment is distinct from before_comments->>o.id::text) then raise exception 'An existing order comment was changed';end if;
 if has_function_privilege('anon','public.teplo_job_customer_comments(uuid[])','EXECUTE') or has_function_privilege('anon','public.place_teplo_demo_commented_cart(jsonb,text,text,text,text,text,text,uuid,text,text)','EXECUTE') then raise exception 'Anonymous access to private comment API';end if;
end $$;
rollback;
